// 计算阶乘的多种方法
function factorialRecursive(n) {
    if (n <= 1) return 1;
    return n * factorialRecursive(n - 1);
}

function factorialIterative(n) {
    let result = 1;
    for (let i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

// 测试阶乘计算
const numbers = [5, 6, 7, 8];
console.log("阶乘计算结果:");
for (const num of numbers) {
    console.log(`${num}! = ${factorialRecursive(num)}`);
}

const n = 10;
console.log(`
递归方法: ${n}! = ${factorialRecursive(n)}`);
console.log(`迭代方法: ${n}! = ${factorialIterative(n)}`);
